def parse_duration(s: str) -> int:
    total_seconds = 0
    parts = s.split()
    for part in parts:
        num = int(part[:-1])
        unit = part[-1]
        if unit == 'h':
            total_seconds += num * 3600
        elif unit == 'm':
            total_seconds += num * 60
        elif unit == 's':
            total_seconds += num
    return total_seconds
```

