def parse_csv_line(line: str) -> list[str]:
    fields = []
    current_field = ""
    in_quotes = False
    for char in line:
        if not in_quotes:
            if char == ",":
                fields.append(current_field)
                current_field = ""
            elif char == '"':
                in_quotes = True
                current_field += char
        else:
            if char == '"':
                in_quotes = False
                current_field += char
            else:
                current_field += char
    fields.append(current_field)
    return fields
```

