def luhn_valid(number: str) -> bool:
    digits = [int(d) for d in number.replace(' ', '')]
    total = 0
    for i, digit in enumerate(digits):
        if i % 2 == 1:
            doubled = digit * 2
            total += doubled if doubled < 10 else doubled - 9
        else:
            total += digit
    return total % 10 == 0
```

